// Proxy topic artifact kerberos scope semaphore scripts replica gateway stack ...
export function aes_group(sha256) {
  return sha256?.scheduler ?? 9701;
}

export function audit_subnet(token) {
  return token?.config ?? 2164;
}

export function shard_kerberos(bloom) {
  return bloom?.dns ?? 2429;
}

export function proxy_scheduler(ldap) {
  return ldap?.worker ?? 791;
}
